import { useEffect, useState } from "react";
import getContract from "../utils/getVotingContract";

function VotingPage() {
  const [candidates, setCandidates] = useState([]);
  const [hasVoted, setHasVoted] = useState(false);
  const [account, setAccount] = useState("");
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    loadVotingData();
  }, []);

  const loadVotingData = async () => {
    try {
      const contract = await getContract();
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      const userAddress = accounts[0];
      setAccount(userAddress);

      const voted = await contract.hasUserVoted(userAddress); // ✅ use hasUserVoted() instead of mapping directly
      setHasVoted(voted);

      const count = await contract.getCandidateCount();
      const candidateList = [];
      for (let i = 0; i < count; i++) {
        const name = await contract.getCandidateName(i);
        candidateList.push({ id: i, name });
      }
      setCandidates(candidateList);
    } catch (err) {
      console.error("Failed to load voting data:", err);
      setError("Failed to load voting data.");
    } finally {
      setLoading(false);
    }
  };

  const handleVote = async (id) => {
    try {
      const contract = await getContract();
      const tx = await contract.vote(id);
      await tx.wait();
      alert("Voted successfully!");
      setHasVoted(true);
    } catch (err) {
      console.error("Voting failed:", err);
      alert("Voting failed. Please try again.");
    }
  };

  if (loading) return <div>Loading voting data...</div>;
  if (error) return <div style={{ color: "red" }}>{error}</div>;

  return (
    <div>
      <h2>Welcome: {account}</h2>
      <h3>{hasVoted ? "You have already voted." : "Please cast your vote"}</h3>
      {candidates.map((candidate) => (
        <div key={candidate.id} style={{ marginBottom: "10px" }}>
          <span style={{ marginRight: "10px" }}>{candidate.name}</span>
          {!hasVoted ? (
            <button onClick={() => handleVote(candidate.id)}>Vote</button>
          ) : (
            <button disabled>Voted</button>
          )}
        </div>
      ))}
    </div>
  );
}

export default VotingPage;
